'use strict';
const E=window.Explorer;
const runStates={running:['探索中','blue','clock'],waiting:['等待操作','amber','pause'],passed:['已完成','green','check'],failed:['未通过','red','alert'],stopped:['已停止','','stop']};
const stepStates={pending:['待执行','','clock'],sent:['动作已发送','blue','arrow'],verified:['结果已验证','green','check'],failed:['验证未通过','red','alert'],recovered:['重试后恢复','green','refresh'],insufficient:['证据不足','amber','info']};
const badge=(state,kind='run')=>{const s=(kind==='run'?runStates:stepStates)[state]||['尚未探索','','clock'];return `<span class="badge ${s[1]}">${icon(s[2])}${s[0]}</span>`;};
const dateTime=t=>new Date(t).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});
const clock=t=>new Date(t).toLocaleTimeString('zh-CN',{hour12:false});
const duration=n=>`${String(Math.floor(Math.max(0,n)/60)).padStart(2,'0')}:${String(Math.floor(Math.max(0,n))%60).padStart(2,'0')}`;
const ongoing=r=>r&&['running','waiting'].includes(r.status);
const editable=c=>!c||c.owner==='我'&&!c.control;
const tag=t=>`<span class="tag">${esc(t)}</span>`;
let screen={kind:'draft'},offline=!navigator.onLine,toastTimer,playTimer,dialogReturn,modalKind='',modalContext={},unsavedEdit=false;
let workspaceStates=new Map(Object.entries(E.state.views||{})),sideQuery='',showArchived=false,menuId=null,observerHidden=false;
const deviceLoading=new Set(),deviceStarting=new Set();
E.state.savedDrafts||={};
const getCase=()=>screen.caseId?A.getCase(screen.caseId):null;
const currentRun=()=>screen.runId?A.getRun(screen.runId):null;
const scratch=()=>screen.draftId?E.state.savedDrafts[screen.draftId]:E.state.draft;
const keyFor=()=>screen.caseId?screen.caseId+':'+(screen.runId||'pending'):screen.draftId||'new';
function viewState(){const key=keyFor();if(!workspaceStates.has(key))workspaceStates.set(key,{input:'',scroll:null,following:true,unread:0,rightTab:'live',pinned:false,selected:null,selectedVersion:'latest',replay:0,playing:false,connected:!offline,lastFrame:null,lastAt:null});return workspaceStates.get(key);}
function save(){E.state.views=Object.fromEntries(workspaceStates);if(!A.save())toast('存储不可用，当前内容仅保留在本次打开期间。');}
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4000);}
function rememberView(){const input=$('#goal-input'),c=getCase();if(input){const d=c?E.draft(c):scratch();if(d)d.text=input.value;}const scroll=$('#message-scroll');if(scroll){const s=viewState();s.scroll=scroll.scrollTop;s.input=$('#composer-input')?.value??s.input;}save();}
function closeMenu(){const el=$('#case-menu');if(el)el.hidden=true;menuId=null;}
function go(route){rememberView();closeMenu();closeDialog();stopReplay();if(location.hash==='#/'+route)render();else location.hash='/'+route;}
function resolveRoute(){const p=location.hash.replace(/^#\/?/,'').split('/');if(p[0]==='draft'&&E.state.savedDrafts[p[1]])return {kind:'draft',draftId:p[1]};if(p[0]==='run'){const r=A.getRun(p[1]);if(r)return {kind:'workspace',caseId:r.caseId,runId:r.id};}if(p[0]==='case'){const c=A.getCase(p[1]);if(!c)return {kind:'missing'};const explicit=p[2]==='run'?A.getRun(p[3]):null;if(p[2]==='run'&&(!explicit||explicit.caseId!==c.id))return {kind:'missing'};const r=explicit||A.active(c.id)||(c.pending?null:A.runsFor(c.id)[0]);return {kind:r||c.pending?'workspace':'draft',caseId:c.id,runId:r?.id||null};}return {kind:'draft'};}
function newCase(){rememberView();if(E.state.draft.text.trim()){const id='draft-'+Date.now();E.state.savedDrafts[id]={...A.clone(E.state.draft),at:Date.now()};}if(!getCase()&&!screen.draftId&&$('#goal-input'))$('#goal-input').value='';E.state.draft={text:'',context:E.valid(E.state.lastContext)?A.clone(E.state.lastContext):E.empty()};workspaceStates.delete('new');save();go('new');requestAnimationFrame(()=>$('#goal-input')?.focus());}
function shell(){if($('#explorer-shell'))return;$('#app').innerHTML=`<div class="explorer-shell" id="explorer-shell"><aside class="case-sidebar" id="case-sidebar" aria-label="Cases"><header class="sidebar-brand"><a href="#/new" class="od-row brand">${logo()}<span>ARTEMIS</span></a>${ibtn('back','toggle-sidebar','收起 Case 侧栏')}</header><button class="btn sidebar-new" data-action="new">${icon('plus')}新建 Case<span class="key-hint">N</span></button><label class="sidebar-search">${icon('search')}<input id="sidebar-search" type="search" placeholder="搜索 Cases" aria-label="搜索 Cases"></label><div class="sidebar-caption" id="sidebar-caption">最近使用</div><nav class="sidebar-list" id="sidebar-list" aria-label="Case 列表"></nav><footer class="sidebar-footer"><button data-action="archives" id="archive-toggle">${icon('archive')}<span>已归档</span></button><button data-action="settings">${icon('settings')}<span>设置</span></button><div class="sidebar-account"><span class="avatar me">QA</span><span>本地工作区</span><span class="sample-label">模拟</span></div></footer></aside><button class="sidebar-backdrop" data-action="toggle-sidebar" aria-label="收起 Case 侧栏"></button><section class="explorer-main"><header class="explorer-toolbar" id="explorer-toolbar"></header><main class="explorer-stage" id="explorer-stage"></main></section></div><div id="case-menu" class="row-menu" role="menu" hidden></div>`;}
function updateShell(){const root=$('#explorer-shell');root.classList.toggle('sidebar-collapsed',!!E.state.collapsed);root.classList.toggle('observer-hidden',observerHidden);}
function renderSidebar(){const root=$('#sidebar-list');if(!root)return;$('#sidebar-caption').textContent=showArchived?'已归档 · 可恢复':'最近使用';$('#archive-toggle').classList.toggle('active',showArchived);$('#archive-toggle span').textContent=showArchived?'返回最近使用':'已归档';const q=sideQuery.trim().toLowerCase();const cases=A.data.cases.filter(c=>!!c.archived===showArchived&&[c.name,c.id].join(' ').toLowerCase().includes(q)).sort((a,b)=>(b.lastUsed||b.updated)-(a.lastUsed||a.updated));const drafts=showArchived?[]:Object.entries(E.state.savedDrafts).filter(([,d])=>d.text.toLowerCase().includes(q));root.innerHTML=drafts.map(([id,d])=>`<div class="sidebar-item ${screen.draftId===id?'active':''}"><a class="case-open" href="#/draft/${id}"><span class="case-item-name">${esc(d.text.slice(0,36))}</span><small>未提交草稿</small></a></div>`).join('')+cases.map(c=>{const r=A.active(c.id);return `<div class="sidebar-item ${getCase()?.id===c.id?'active':''}"><a class="case-open" href="#/case/${c.id}" ${getCase()?.id===c.id?'aria-current="page"':''}><span class="case-item-name">${esc(c.name)}</span><small data-case-state="${c.id}">${r?'● '+runStates[r.status][0]:c.pending?'待选设备':!A.runsFor(c.id).length?'草稿':''}</small></a>${ibtn('more','case-menu','更多操作：'+c.name,`data-id="${c.id}" aria-haspopup="menu"`)}</div>`;}).join('');if(!cases.length&&!drafts.length)root.innerHTML=`<p class="sidebar-empty">${q?'没有匹配的 Case':showArchived?'没有已归档的 Case':'新探索提交后会出现在这里'}</p>`;}
function updateSideStatus(){for(const el of $$('[data-case-state]')){const c=A.getCase(el.dataset.caseState),r=A.active(c.id);el.textContent=r?'● '+runStates[r.status][0]:c.pending?'待选设备':!A.runsFor(c.id).length?'草稿':'';}}
function fixedContext(r){const cfg=r.config;return `<div class="frozen-context"><span>${esc(cfg.appName||'产品未记录')}</span><span>${esc(cfg.environment||'环境未记录')}</span><span>${esc(cfg.platform||'平台未记录')}</span><span class="context-device">${esc(cfg.device||'设备未记录')}</span><span class="context-lock">${icon('lock')}${ongoing(r)?'本次探索已固定':'历史快照'}</span></div>`;}
function contextBar(ctx,scope='draft'){const product=E.products.find(p=>p.id===ctx.productId),environment=product?.environments.find(e=>e.id===ctx.environment);return `<div class="context-selector" data-context-scope="${scope}">${scope==='next'?'<span class="context-caption">下一次探索</span>':''}<label><span>产品</span><select aria-label="${scope==='next'?'下一次探索产品':'产品'}" data-context="productId"><option value="">选择产品</option>${E.products.map(p=>`<option value="${p.id}" ${ctx.productId===p.id?'selected':''}>${p.name}（示例）</option>`).join('')}</select></label><label><span>环境</span><select aria-label="${scope==='next'?'下一次探索环境':'环境'}" data-context="environment" ${!product?'disabled':''}>${!product?'<option value="">先选产品</option>':product.environments.map(e=>`<option ${ctx.environment===e.id?'selected':''}>${e.id}</option>`).join('')}</select></label><label><span>平台</span><select aria-label="${scope==='next'?'下一次探索平台':'平台'}" data-context="platform" ${!environment?'disabled':''}>${!environment?'<option value="">先选环境</option>':environment.platforms.map(p=>`<option ${ctx.platform===p?'selected':''}>${p}</option>`).join('')}</select></label></div>`;}
function renderHeader(){const c=getCase(),r=currentRun(),runs=c?A.runsFor(c.id):[];$('#explorer-toolbar').innerHTML=`<div class="toolbar-leading">${ibtn('grid','toggle-sidebar',E.state.collapsed?'展开 Case 侧栏':'收起 Case 侧栏',`aria-expanded="${!E.state.collapsed}"`)}${ibtn('plus','new','新建 Case')}<span class="toolbar-divider"></span><div class="workspace-title"><strong>${esc(c?.name||'新探索')}</strong>${c?`<span>${c.id}</span>`:'<span>未提交草稿</span>'}</div></div><div class="toolbar-trailing">${c&&runs.length?`<select id="run-picker" aria-label="探索记录">${c.pending?`<option value="pending" ${!r?'selected':''}>新探索 · 待选设备</option>`:''}${runs.map((x,i)=>`<option value="${x.id}" ${r?.id===x.id?'selected':''}>${i===0?'最近一次探索':'历史探索'} · ${runStates[x.status][0]} · ${dateTime(x.started)} · ${x.id}</option>`).join('')}</select>`:''}${r?badge(r.status):c?.pending?'<span class="badge amber">待选设备</span>':''}${r&&ongoing(r)?`${r.status==='waiting'&&!r.custom?btn('继续','resume','small','play'):''}${btn('停止','stop','small','stop')}`:''}${screen.kind==='workspace'?ibtn('device','toggle-observer',observerHidden?'展开观察区':'收起观察区'):''}${ibtn('help','help','原型说明')}</div>`;}
function render(){screen=resolveRoute();shell();updateShell();renderSidebar();renderHeader();document.title=(getCase()?.name||'开始探索')+' · Artemis';if(screen.kind==='missing'){$('#explorer-stage').innerHTML='<div class="workspace-welcome"><h2>未找到这个 Case</h2><button class="btn" data-action="new">开始新探索</button></div>';return;}if(screen.kind==='draft')renderDraft();else renderWorkspace();}
function renderDraft(){const c=getCase(),d=c?E.draft(c):scratch();const disabled=c&&(c.archived||!editable(c));$('#explorer-stage').innerHTML=`<section class="exploration-entry"><div class="entry-heading"><span class="entry-mark">${logo()}</span><h1>从这里开始探索</h1><p>描述目标，与 Artemis 一起观察产品如何运作。</p></div>${contextBar(d.context)}<form id="goal-form" class="exploration-input"><label for="goal-input" class="sr-only">探索目标</label><textarea id="goal-input" rows="5" maxlength="4000" placeholder="描述你想探索的功能、流程或验证目标" ${disabled?'disabled':''}>${esc(d.text)}</textarea><p id="goal-error" class="field-error" role="alert" hidden></p><footer><span>HappyCoding <span class="entry-divider">·</span> 提交后选择设备</span><button type="submit" class="btn primary" ${disabled?'disabled':''}>开始探索 ${icon('arrow')}</button></footer></form><div class="entry-bottom">${c?.archived?'<span>已归档，恢复后可继续探索</span>':`<button class="example-prompt" data-action="example-goal">${icon('target')}探索邮箱登录与异常恢复</button>`}<span>产品目录与执行均为模拟</span></div></section>`;requestAnimationFrame(()=>$('#goal-input')?.focus());}
function renderWorkspace(){const c=getCase(),r=currentRun(),s=viewState();$('#explorer-stage').innerHTML=`<div class="workspace-context" id="workspace-context">${r?fixedContext(r):contextBar(E.context(c.pending.snapshot.config),'pending')}</div>${c.archived?`<div class="archive-notice">此 Case 已归档，历史仍可查看。${btn('恢复','restore','text','',`data-id="${c.id}"`)}</div>`:''}<div class="workspace-grid" id="workspace-grid"><section class="conversation"><header class="conversation-title"><div class="od-row"><span class="agent-symbol">A</span><h2>探索过程</h2></div><span class="small muted" id="agent-status">${r?ongoing(r)?'HappyCoding · 模拟执行':'已结束 · 记录已保留':'等待选择设备'}</span></header><div class="message-scroll" id="message-scroll"><div class="message-list" id="message-list"></div></div><div class="new-events-bar" id="new-events-bar" hidden></div><footer class="composer" id="composer"></footer></section><div class="split-handle" id="split-handle" role="separator" tabindex="0" aria-label="调整消息流与观察区宽度" aria-orientation="vertical" aria-valuemin="35" aria-valuemax="65" aria-valuenow="50"></div><section class="device-panel"><header class="device-tabs"><nav class="tabs" aria-label="观察区域"><button class="tab" data-action="right-tab" data-value="live">${icon('live')}直播</button><button class="tab" data-action="right-tab" data-value="plan">${icon('file')}TaskPlan${r&&ongoing(r)?'<span class="activity-dot"></span>':''}</button><button class="tab" data-action="right-tab" data-value="replay">${icon('play')}回放</button></nav>${ibtn('file','pin-plan','与直播并排查看计划',`aria-pressed="${s.pinned}"`)}</header><div id="device-content" class="device-content"></div></section></div>`;renderMessages();renderComposer();renderRight();bindWorkspace();requestAnimationFrame(()=>{const scroll=$('#message-scroll');if(!scroll)return;scroll.scrollTop=s.scroll??scroll.scrollHeight;s.following=scroll.scrollHeight-scroll.clientHeight-scroll.scrollTop<72;});}
function deviceCard(c){const p=c.pending,list=E.candidates(p),loading=deviceLoading.has(p.id),starting=deviceStarting.has(p.id),ready=list.filter(d=>d.state==='ready'&&!offline),selected=ready.find(d=>d.id===p.deviceId);return `<article class="message agent"><div class="message-avatar">A</div><div class="message-body"><div class="message-byline"><strong>Artemis</strong><time>${clock(p.at)}</time></div><p class="message-text">目标已收到，选择设备后开始探索。</p><section class="device-choice" aria-label="选择执行设备"><header><div><h3>选择执行设备</h3><p>${esc(p.snapshot.config.appName)} · ${esc(p.snapshot.config.environment)} · ${esc(p.snapshot.config.platform)}</p></div>${ibtn('refresh','refresh-devices','刷新设备',loading||starting?'disabled':'')}</header>${loading||starting?`<div class="progress-line" role="status">${starting?'正在准备设备与探索…':'正在加载设备状态…'}</div>`:''}<div class="device-options">${list.map(d=>`<label class="device-option ${p.deviceId===d.id?'selected':''} ${d.state!=='ready'||offline?'unavailable':''}"><input type="radio" name="execution-device" value="${d.id}" ${p.deviceId===d.id?'checked':''} ${d.state!=='ready'||offline||loading||starting?'disabled':''}><span class="od-field od-fill"><strong>${esc(d.name)}</strong><small>${esc(d.detail)}</small></span><span class="device-status ${d.state==='ready'&&!offline?'available':''}">${offline?'离线':{ready:'已连接 · 可用',busy:'占用中',offline:'离线'}[d.state]}</span></label>`).join('')}</div>${!ready.length&&!loading?`<div class="device-empty"><strong>暂无可用设备</strong><p>连接此平台的设备，或等待占用结束后刷新。</p>${btn('连接指引','device-guide','text')}</div>`:''}<footer><span class="small muted">${ready.length} 台可用 · 模拟设备</span>${btn('确认并开始','start-device','primary','play',!selected||offline||loading||starting?'disabled':'')}</footer></section></div></article>`;}
function renderComposer(){const c=getCase(),r=currentRun(),s=viewState(),pending=c?.pending&&!r,other=A.active(c.id)&&A.active(c.id).id!==r?.id,locked=c.archived||!editable(c)||pending||other;const active=ongoing(r);$('#composer').innerHTML=`${r&&!active&&!other&&!c.archived?contextBar(E.draft(c).context,'next'):''}<form id="composer-form"><label class="composer-label" for="composer-input">${active?'补充指令':pending?'探索目标已提交':'再次探索'}</label><textarea id="composer-input" rows="2" maxlength="4000" placeholder="${active?'补充观察重点或下一步要求':pending?'请在上方选择设备':'补充下一次探索的要求，或直接沿用上次目标'}" ${locked?'disabled':''}>${esc(s.input)}</textarea><p id="composer-error" class="field-error" role="alert" hidden></p><div class="composer-footer"><span>${c.archived?'恢复后可再次探索':other?'此 Case 有正在进行的探索':pending?'选择设备后继续':active?'提交到当前探索':'保留历史 · 创建新的探索记录'}</span><button type="submit" class="btn ${active?'':'primary'}" ${locked?'disabled':''}>${active?'提交补充指令':'再次探索'}${icon(active?'send':'refresh')}</button></div>${other?btn('回到进行中的探索','open-active','text'):''}</form>`;}
function refreshDevices(c){const p=c?.pending;if(!p)return;deviceLoading.add(p.id);if(getCase()?.id===c.id&&!currentRun())renderMessages();setTimeout(()=>{deviceLoading.delete(p.id);if(c.pending?.id!==p.id)return;if(!E.candidates(p).some(d=>d.id===p.deviceId&&d.state==='ready'))p.deviceId=null;save();if(getCase()?.id===c.id&&!currentRun())renderMessages();},600);}
function refreshRun(r){updateSideStatus();if(currentRun()?.id!==r.id)return;const s=viewState(),scroll=$('#message-scroll');renderHeader();if(s.following){renderMessages();scroll.scrollTop=scroll.scrollHeight;s.scroll=scroll.scrollTop;}else{s.unread++;updateNewEvents();}if(s.rightTab==='live'||s.rightTab==='plan')renderRight();if(!ongoing(r))renderComposer();save();}
function submitGoal(text){const c=getCase(),d=c?E.draft(c):scratch();const error=$('#goal-error')||$('#composer-error');if(!text.trim()){error.textContent='请描述想探索的功能、流程或验证目标。';error.hidden=false;return;}if(!E.valid(d.context)){error.textContent='请明确选择产品、环境和平台。';error.hidden=false;return;}if(c&&(!editable(c)||c.archived))return;let oldScratch;if(!c&&screen.draftId){oldScratch=E.state.draft;E.state.draft=d;}const created=E.submit(c,text);if(oldScratch)E.state.draft=oldScratch;if(!created)return toast('当前探索尚未结束或正在等待设备。');if(screen.draftId)delete E.state.savedDrafts[screen.draftId];viewState().input='';if($('#goal-input'))$('#goal-input').value='';if($('#composer-input'))$('#composer-input').value='';workspaceStates.delete(created.id+':pending');save();go('case/'+created.id);refreshDevices(created);}
function showHelp(){dialog('探索工作区',`<p>明确选择产品、环境和平台，提交目标后在消息流选择设备。新 Case 首次提交时保存；再次探索保留历史，补充指令归属当前探索。</p><p>当前产品目录、设备、直播、执行与新增 TaskPlan 均为明确标记的本地模拟。邮箱登录示例可完整演示失败、重试和恢复；其他目标只记录提交，不生成虚构的通过结果。</p><p>模拟决策截图标记为模拟输入帧。旧记录缺少的模型输出、截图和 TaskPlan 不补造。</p><p>离开 Case 不停止探索。关闭整个页面后本地执行暂停，下次打开可继续。</p>`);}
function openMenu(button,c){closeMenu();menuId=c.id;const el=$('#case-menu');el.innerHTML=`<button role="menuitem" data-action="rename" data-id="${c.id}" ${!editable(c)?'disabled':''}>${icon('edit')}重命名</button><button role="menuitem" data-action="${c.archived?'restore':'archive'}" data-id="${c.id}" ${!editable(c)||A.active(c.id)||c.pending?'disabled':''}>${icon('archive')}${c.archived?'恢复到 Cases':'归档'}</button>`;el.hidden=false;const rect=button.getBoundingClientRect();el.style.left=Math.min(innerWidth-200,Math.max(8,rect.left))+'px';el.style.top=Math.min(innerHeight-el.offsetHeight-8,rect.bottom+4)+'px';el.querySelector('button:not(:disabled)')?.focus();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b){const a=e.target.closest('a[href^="#/"]');if(a){e.preventDefault();const route=a.getAttribute('href').slice(2),id=route.split('/')[1];if(route.startsWith('case/'))E.touch(A.getCase(id));go(route);return;}if(!e.target.closest('#case-menu'))closeMenu();return;}if(b.disabled)return;const action=b.dataset.action,c=b.dataset.id&&['case-menu','rename','archive','restore'].includes(action)?A.getCase(b.dataset.id):getCase(),r=currentRun(),s=viewState();
if(action==='new')return newCase();
if(action==='toggle-sidebar'){rememberView();E.state.collapsed=!E.state.collapsed;save();updateShell();renderHeader();return;}
if(action==='toggle-observer'){observerHidden=!observerHidden;updateShell();renderHeader();return;}
if(action==='archives'){showArchived=!showArchived;return renderSidebar();}
if(action==='case-menu')return openMenu(b,c);
if(action==='rename'){closeMenu();modalContext={caseId:c.id};return dialog('重命名 Case',`<form id="rename-form"><label class="field">Case 名称<input name="name" required maxlength="100" value="${esc(c.name)}" autocomplete="off"></label><p class="field-error" id="rename-error" hidden></p></form>`,btn('取消','close-dialog')+'<button class="btn primary" type="submit" form="rename-form">保存</button>');}
if(action==='archive'){closeMenu();return confirmDialog('归档 Case？','从常用侧栏收起，探索记录仍保留，可在已归档中恢复。','归档',()=>{c.archived=true;save();render();});}
if(action==='restore'){c.archived=false;save();closeMenu();showArchived=false;render();return toast('已恢复到 Cases。');}
if(action==='confirm'){const fn=modalContext.callback;closeDialog();return fn?.();}
if(action==='close-dialog')return closeDialog();
if(action==='help')return showHelp();
if(action==='settings')return dialog('设置','<dl class="facts"><dt>执行工具</dt><dd>HappyCoding</dd><dt>测试账号</dt><dd>由内部自动获取</dd><dt>视频与日志</dt><dd>默认保留</dd></dl><p class="muted" style="margin-top:16px">当前为本地模拟。产品、环境和平台在探索区明确选择，设备在提交目标后选择。</p>');
if(action==='example-goal'){const el=$('#goal-input');el.value='探索邮箱登录流程：验证密码页与首页，并观察首次点击失败后的重试恢复。';(c?E.draft(c):scratch()).text=el.value;save();el.focus();return;}
if(action==='refresh-devices')return refreshDevices(c);
if(action==='device-guide')return dialog('连接设备','<p>连接所选平台的设备并完成调试授权，确认设备未被其他探索占用后，刷新设备卡片。</p><p>当前为模拟目录。客户门户的 Sandbox 环境用于展示无可用设备状态；真实设备服务尚未接入。</p>');
if(action==='start-device'){const p=c?.pending;if(!p||offline||deviceStarting.has(p.id))return;const revision=p.deviceRevision;deviceStarting.add(p.id);renderMessages();setTimeout(()=>{deviceStarting.delete(p.id);if(c.pending?.id!==p.id||p.deviceRevision!==revision){if(getCase()?.id===c.id&&!currentRun())renderMessages();return;}const run=E.start(c,p.deviceId);if(!run){if(getCase()?.id===c.id&&!currentRun())renderMessages();return toast('设备已不可用，请刷新后重新选择。');}if(run.status==='running')E.tick(run);if(getCase()?.id===c.id&&!currentRun())go(`case/${c.id}/run/${run.id}`);else{updateSideStatus();toast(c.name+' 已开始探索。');}},650);return;}
if(action==='resume'){E.tick(r,true);return refreshRun(r);}
if(action==='stop')return confirmDialog('停止本次探索？','停止后保留当前消息、证据和历史记录。','停止探索',()=>{E.stop(r);refreshRun(r);});
if(action==='open-active')return go(`case/${c.id}/run/${A.active(c.id).id}`);
if(action==='right-tab'){stopReplay();s.rightTab=b.dataset.value;return renderRight();}
if(action==='pin-plan'){s.pinned=!s.pinned;s.rightTab='live';return renderRight();}
if(action==='show-plan'){s.rightTab='plan';observerHidden=false;updateShell();return renderRight();}
if(action==='plan-event'){observerHidden=false;updateShell();return locateMessage(b.dataset.id);}
if(action==='select-message'||action==='replay-message')return locateMessage(b.dataset.id);
if(action==='follow-messages')return followMessages();
if(action==='open-replay'){s.rightTab='replay';observerHidden=false;updateShell();return renderRight();}
if(action==='play-replay')return toggleReplay();
if(action==='back-live'){stopReplay();s.rightTab='live';return renderRight();}
if(action==='run-facts')return showRunFacts(r);
if(action==='result-evidence'){const e=allEvents(r).find(e=>e.status==='failed');if(e)locateMessage(e.id);return;}
if(action==='open-image')return showImage(b.dataset.kind,Number(b.dataset.at),b.dataset.id,b.dataset.role);
if(action==='zoom-in'||action==='zoom-out'){modalContext.zoom=Math.max(.75,Math.min(2,modalContext.zoom+(action==='zoom-in'?.25:-.25)));return renderImageDialog();}
if(action==='reconnect'){if(offline)return toast('网络仍未恢复。');s.connected=true;s.lastAt=null;s.lastFrame=null;r.connectionEvents.push({at:Date.now(),state:'connected'});save();renderRight();return toast('已重新连接模拟直播。');}
});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='sidebar-search'){sideQuery=el.value;renderSidebar();}if(el.id==='goal-input'){(getCase()?E.draft(getCase()):scratch()).text=el.value;save();}if(el.id==='composer-input'){viewState().input=el.value;save();}if(el.id==='replay-position'){stopReplay();viewState().replay=Number(el.value);renderRight();}});
document.addEventListener('change',e=>{const el=e.target,c=getCase();if(el.dataset.context){rememberView();const scope=el.closest('[data-context-scope]').dataset.contextScope;if(c&&A.active(c.id)){toast('执行中的上下文已固定，请结束后开始新的探索。');return;}let result;if(!c&&screen.draftId){const old=E.state.draft;E.state.draft=scratch();result=E.setContext(null,el.dataset.context,el.value);E.state.draft=old;}else result=E.setContext(c,el.dataset.context,el.value);if(!result)return;if(scope==='pending'){const id=c.pending.id;deviceStarting.delete(id);$('#workspace-context').innerHTML=contextBar(E.context(c.pending.snapshot.config),'pending');refreshDevices(c);}else if(scope==='next')renderComposer();else renderDraft();save();toast(scope==='next'?'仅用于下一次探索，历史配置保持不变。':scope==='pending'?'上下文已更新，请重新选择设备。':result.adjusted?'环境与平台已更新为此产品的有效选项。':'探索上下文已更新。');}if(el.name==='execution-device'&&c?.pending){c.pending.deviceId=el.value;save();renderMessages();}if(el.id==='run-picker'){rememberView();go(el.value==='pending'?`case/${c.id}`:`case/${c.id}/run/${el.value}`);}if(el.id==='plan-version'){viewState().selectedVersion=el.value;renderRight();}});
document.addEventListener('submit',e=>{const f=e.target;if(!['goal-form','composer-form','rename-form'].includes(f.id))return;e.preventDefault();if(f.id==='goal-form')return submitGoal($('#goal-input').value);if(f.id==='composer-form'){const r=currentRun(),text=$('#composer-input').value.trim();if(ongoing(r)){if(!text){$('#composer-error').textContent='请输入补充指令。';$('#composer-error').hidden=false;return;}A.addInstruction(r,text);viewState().input='';$('#composer-input').value='';followMessages();save();return toast('指令已记录，真实采纳状态待接入。');}return submitGoal(text||r?.intent?.text||r?.snapshot.objective||'');}const c=A.getCase(modalContext.caseId),name=String(new FormData(f).get('name')||'').trim();if(!name){$('#rename-error').hidden=false;$('#rename-error').textContent='请填写 Case 名称。';return;}if(c&&editable(c)){c.name=name;c.updated=Date.now();save();closeDialog();renderHeader();renderSidebar();toast('名称已更新，历史快照保持不变。');}});
window.addEventListener('hashchange',()=>{rememberView();stopReplay();closeDialog();closeMenu();render();});
window.addEventListener('beforeunload',rememberView);
window.addEventListener('offline',()=>{offline=true;for(const [key,state] of workspaceStates){const run=A.getRun(key.split(':')[1]);if(run&&ongoing(run)){state.connected=false;state.lastFrame=latestFrame(run)?.frame;state.lastAt=latestFrame(run)?.at;}}if(currentRun())renderRight();if(getCase()?.pending&&!currentRun())renderMessages();save();toast('直播连接断开，任务状态单独保留。');});
window.addEventListener('online',()=>{offline=false;if(getCase()?.pending&&!currentRun())renderMessages();if(currentRun())renderRight();toast('网络恢复，可重新连接直播或刷新设备。');});
window.addEventListener('resize',closeMenu);
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();if(menuId&&['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();const items=$$('#case-menu button:not(:disabled)'),i=items.indexOf(document.activeElement);items[(i+(e.key==='ArrowDown'?1:-1)+items.length)%items.length]?.focus();}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){const f=document.activeElement.closest('form');if(f?.matches('#goal-form,#composer-form')){e.preventDefault();f.requestSubmit();}}if(e.key.toLowerCase()==='n'&&!e.ctrlKey&&!e.metaKey&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#modal').open)newCase();});
setInterval(()=>{for(const r of A.data.runs)if(r.status==='running'&&!r.custom){E.tick(r);refreshRun(r);}updateSideStatus();},3000);
history.scrollRestoration='manual';if(!E.state.layoutInitialized){E.state.collapsed=innerWidth<980;E.state.layoutInitialized=true;save();}
render();
